const K1: f64 = 1.2;
const B: f64 = 0.75;
/// BM25F field weights: a heading line counts double, path tokens count in every unit of the doc.
const HEADING_WEIGHT: f64 = 2.0;
const PATH_WEIGHT: f64 = 1.0;
const GENERATED_HEAD_LINES: usize = 10;
const GENERATED_MARKERS: [&str; 5] = [
    "generated by",
    "do not edit",
    "@generated",
    "auto-generated",
    "autogenerated",
];
fn for_each_token(text: &str, mut f: impl FnMut(&str)) {
    for word in text.split(|c: char| !c.is_alphanumeric()) {
        if word.is_empty() {
            continue;
        }
        let mut start = 0;
        let mut prev_lower = false;
        for (i, c) in word.char_indices() {
            if c.is_uppercase() && prev_lower {
                f(&word[start..i]);
                start = i;
            }
            prev_lower = c.is_lowercase() || c.is_numeric();
        }
        f(&word[start..]);
    }
}

/// Lowercased alphanumeric words, camelCase split, first occurrence order, deduplicated.
#[must_use]
pub fn query_terms(query: &str) -> Vec<String> {
    let mut terms: Vec<String> = Vec::new();
    for_each_token(query, |tok| {
        let t = tok.to_lowercase();
        if !terms.contains(&t) {
            terms.push(t);
        }
    });
    terms
}

#[derive(Debug, Clone, Default)]
pub(super) struct TermStats {
    len: f64,
    tf: Vec<f64>,
}

impl TermStats {
    pub(super) fn matches(&self) -> bool {
        self.tf.iter().any(|&t| t > 0.0)
    }
}

fn eq_lowercase(tok: &str, term: &str) -> bool {
    tok.chars().flat_map(char::to_lowercase).eq(term.chars())
}

fn add_tokens(stats: &mut TermStats, text: &str, terms: &[String], weight: f64) {
    for_each_token(text, |tok| {
        stats.len += weight;
        for (slot, term) in stats.tf.iter_mut().zip(terms) {
            if eq_lowercase(tok, term) {
                *slot += weight;
            }
        }
    });
}

pub(super) fn unit_stats(heading: &str, body: &str, path: &str, terms: &[String]) -> TermStats {
    let mut stats = TermStats {
        len: 0.0,
        tf: vec![0.0; terms.len()],
    };
    add_tokens(&mut stats, heading, terms, HEADING_WEIGHT);
    add_tokens(&mut stats, body, terms, 1.0);
    add_tokens(&mut stats, path, terms, PATH_WEIGHT);
    stats
}

pub(super) fn bm25(stats: &TermStats, idf: &[f64], avg_len: f64) -> f64 {
    let norm = (1.0 - B) + B * (stats.len / avg_len.max(1.0));
    stats
        .tf
        .iter()
        .zip(idf)
        .filter(|(tf, _)| **tf > 0.0)
        .map(|(&tf, &w)| w * tf * (K1 + 1.0) / (tf + K1 * norm))
        .sum()
}

pub(super) fn idf_weights(units: &[&TermStats], terms: usize) -> Vec<f64> {
    let n = units.len() as f64;
    (0..terms)
        .map(|i| {
            let df = units.iter().filter(|s| s.tf[i] > 0.0).count() as f64;
            (1.0 + (n - df + 0.5) / (df + 0.5)).ln()
        })
        .collect()
}

pub(super) fn average_len(units: &[&TermStats]) -> f64 {
    if units.is_empty() {
        return 1.0;
    }
    units.iter().map(|s| s.len).sum::<f64>() / units.len() as f64
}

#[must_use]
pub fn is_generated(text: &str) -> bool {
    text.lines().take(GENERATED_HEAD_LINES).any(|line| {
        let lower = line.to_ascii_lowercase();
        GENERATED_MARKERS.iter().any(|m| lower.contains(m))
    })
}
